        local skippedMsg = skipped > 0 and (" (" .. tostring(skipped)) .. " skipped — no price data)" or ""
        local itemsMsg = #postedLinks > 0 and ": " .. table.concat(postedLinks, ", ") or ""
        d((((((((("[" .. ADDON_NAME) .. "] Listed ") .. tostring(posted)) .. " items") .. skippedMsg) .. itemsMsg) .. ". Listing fees: ") .. tostring(totalFees)) .. " gold.")
    end
    ____exports.tradingHouseOpen = true
