            return
        end
        local stackCount = GetSlotStackSize(bagId, slotIndex)
        if stackCount == 0 then
            clearPendingAction(bagId, slotIndex)
            return
        end
        if not IsItemSellableOnTradingHouse(bagId, slotIndex) then
            clearPendingAction(bagId, slotIndex)
            return
        end
