        local cooldown = GetTradingHouseCooldownRemaining()
        if cooldown > 0 then
            zo_callLater(postNextItem, cooldown + 100)
            return
        end
        local candidate = candidates[queueIndex + 1]
        queueIndex = queueIndex + 1
        local stackCount = GetSlotStackSize(candidate.bagId, candidate.slotIndex)
        if stackCount == 0 then
            clearPendingAction(candidate.bagId, candidate.slotIndex)
            postNextItem()
            return
        end
        local listingFee = GetTradingHousePostPriceInfo(candidate.totalPrice)
        local gold = GetCurrencyAmount(CURT_MONEY, CURRENCY_LOCATION_CHARACTER)
        if gold < listingFee then
            d(((((("[" .. ADDON_NAME) .. "] Cannot afford listing fee (") .. tostring(listingFee)) .. "g, have ") .. tostring(gold)) .. "g) — stopping")
            printSummary()
            return
        end
        RequestPostItemOnTradingHouse(candidate.bagId, candidate.slotIndex, candidate.stackCount, candidate.totalPrice)
        clearPendingAction(candidate.bagId, candidate.slotIndex)
        postedLinks[#postedLinks + 1] = candidate.itemLink
        posted = posted + 1
        totalFees = totalFees + listingFee
        zo_callLater(postNextItem, 1000)
    end
    postNextItem()
end
return ____exports
 end,
