                    if rule.action == "sell" and isStolenVal and IsItemLinkContainer(itemLink) then
                        __continue55 = true
                        break
                    end
                    local destination = rule.destination or "nil"
                    if destination == "character-worn:by-priority" then
                        local charId = findEquipCharacterIdByPriority(itemLink)
                        if charId == nil then
                            __continue55 = true
                            break
