                            __continue55 = true
                            break
                        end
                        destination = "companion-worn:" .. name
                    end
                    if destination == "character:by-priority" then
                        local charId
                        if rule.action == "use" and rule.canUnlock then
                            charId = findUnlockCharacterIdByPriority(itemLink, itemType)
                        elseif rule.action == "research" then
                            charId = findResearchCharacterIdByPriority(itemLink)
                        elseif rule.action == "deconstruct" then
                            charId = findInspireCharacterIdByPriority(itemLink)
                        elseif rule.action == "use" then
                            charId = findConsumableCharacterIdByPriority(itemId)
                        end
                        if charId == nil then
                            __continue55 = true
                            break
                        end
                        destination = "character:" .. charId
                    end
                    d((((((____exports.PREFIX .. " Rule #") .. tostring(i)) .. ": action=") .. rule.action) .. ", destination=") .. destination)
                    local condStr = ____exports.describeInlineConditions(rule, ctx)
                    if condStr ~= "" then
                        d((____exports.PREFIX .. " Conditions: ") .. condStr)
                    end
                    return
                until true
                if not __continue55 then
                    break
                end
            end
            i = i + 1
        end
    end
    d(____exports.PREFIX .. " No matching rule")
end
return ____exports
 end,
