            return
        end
        local group = findCooldownGroup(bagId, slotIndex)
        if group then
            local sv = getSavedVariables()
            local ____opt_0 = sv.openCooldowns
            local expiry = ____opt_0 and ____opt_0[group.key]
            local now = GetTimeStamp()
            if expiry == nil or now >= expiry then
                return
            end
            local remaining = expiry - now
            local formatted = ZO_FormatTime(remaining, TIME_FORMAT_STYLE_DESCRIPTIVE_SHORT, TIME_FORMAT_PRECISION_SECONDS, TIME_FORMAT_DIRECTION_DESCENDING)
            self:AddLine(
                ("|cFF4444Cooldown: " .. formatted) .. "|r",
                "",
                1,
                1,
                1,
                BOTTOM,
                MODIFY_TEXT_TYPE_NONE,
                TEXT_ALIGN_CENTER,
                true
            )
