        end
        local dlcRemaining = getDlcDailyCooldownRemaining(bagId, slotIndex)
        if dlcRemaining == nil then
            return
        end
        local formatted = ZO_FormatTime(dlcRemaining, TIME_FORMAT_STYLE_DESCRIPTIVE_SHORT, TIME_FORMAT_PRECISION_SECONDS, TIME_FORMAT_DIRECTION_DESCENDING)
        self:AddLine(
            ("|cFF4444Cooldown: " .. formatted) .. "|r",
            "",
            1,
            1,
            1,
            BOTTOM,
            MODIFY_TEXT_TYPE_NONE,
            TEXT_ALIGN_CENTER,
            true
        )
    end
end
